import { randomUUID } from "node:crypto";

/**
 * Object keys are always generated by the server from UUIDs. User-supplied
 * filenames never become part of a key, which rules out path traversal and
 * key collisions by construction.
 */
const KEY_PATTERN = /^(docs|print|preview|exports)\/[0-9a-f-]{36}\/[0-9a-f-]{36}(\/[0-9]{1,2}\.png|\.pdf|\.json)?$/;

export class UnsafeKeyError extends Error {
  override readonly name = "UnsafeKeyError";
}

export function assertSafeKey(key: string): string {
  if (!KEY_PATTERN.test(key)) throw new UnsafeKeyError(`unsafe object key: ${JSON.stringify(key)}`);
  return key;
}

export const objectKeys = {
  original: (assetId: string, versionId: string) => assertSafeKey(`docs/${assetId}/${versionId}`),
  print: (assetId: string, versionId: string) => assertSafeKey(`print/${assetId}/${versionId}.pdf`),
  preview: (assetId: string, versionId: string, page: number) => assertSafeKey(`preview/${assetId}/${versionId}/${page}.png`),
  export: (userId: string) => assertSafeKey(`exports/${userId}/${randomUUID()}.json`),
};
